using static TinPan.Localization.Loc;

namespace TinPan.ViewModels
{
    /// <summary>
    /// F1 says one of the short lines for the current tab; Ctrl+F1 shows the full guide.
    /// Each section of the guide is translated on its own. Keep README.md in step with these.
    /// </summary>
    public static class HelpText
    {
        public static string Library => T("Library. Arrow through your songs. Enter plays, Space pauses, Left and Right seek. Applications key for extend, cover, downloads and more. Ctrl+F searches. Ctrl+Shift+F8 resumes where you left off. Alt+F for filters.");

        public static string Create => T("Create a song. Set the model, style and voice, then describe a song or use your own lyrics. Tab moves between fields. F5 reloads the models. F8 plays or pauses from here. The window stays open until you press Escape.");

        public static string Trending => T("Trending. Enter plays a song, Space pauses, Left and Right seek. Applications key for more. F5 refreshes.");

        public static string Account => T("Account. Your plan and credits, then Suno's notifications. F2 and Shift+F2 read them from anywhere. F5 refreshes.");

        public static string Playlists => T("Playlists. Pick a playlist and press Enter to open its songs. Enter plays, Space pauses, Left and Right seek, Delete removes a song, Ctrl+Up and Ctrl+Down move it. Applications key for more on either list.");

        public static string Settings => T("Settings. Sign in or out, choose the language, and choose where songs are saved.");

        public static string NotSignedIn => " " + T("You're not signed in. Ctrl+5 opens Settings.");

        public static string Full => string.Join("\n\n", new[]
        {
            T("Anywhere") + "\n" + T("Alt or F10: the menu bar, hidden until then. Every command is in it, with its keys. Left and Right move between menus, Down opens one, Escape or Alt leaves. The Song menu acts on the song selected in the tab you're on.\nTab only stops on what you need: the search box, the list and the volume. The buttons on each page still work with their Alt letters, and everything is in the menu bar.\nF1: short help for where you are.\nCtrl+F1: all commands in a list; Enter runs one. Its first item is this guide.\nCtrl+R: repeat the last message. Ctrl+Shift+R: message history, newest first.\nEscape: step back one level (to the tab headers, or from a playlist's songs to the playlists).\nF2: credits left.\nShift+F2: your plan, when it renews, credits and downloads left. The Account tab lists everything the plan includes.\nF3: what's playing and how far in.\nF5: refresh the current tab.\nCtrl+1 to Ctrl+5: Library, Playlists, Trending, Account, Settings. Each puts you on that page's list or first field.\nCtrl+N: create a song, in a window that stays open. F6 and Shift+F6: move between Tin Pan's open windows.\nCtrl+F: search your songs.") + "\n" + T("The Song menu groups its commands: Download, Make from it (extend, cover, remaster, whole song, stems), Related songs, Comments and Sharing (links, public or private, remixes). Its keys (Ctrl+I, Alt+Enter, Ctrl+L, Ctrl+C, Ctrl+D, Ctrl+E) work in the Library, a playlist's songs and Trending. The Help menu's Speech submenu sets how much Tin Pan says."),
            T("Playing") + "\n" + T("F8 or the Play/Pause media key: play or pause; with nothing playing it starts the selected song on the Library or Playlists tab.\nShift+F8: stop.\nF7 and F9: previous and next song.\nShift+F7 and Shift+F9: back and forward 10 seconds.\nCtrl+F7 and Ctrl+F9: back and forward 10 percent of the song.\nCtrl+F8: back to the start of the song.\nCtrl+Shift+F8: resume the last song where you left off, even after closing Tin Pan.\nF11 and F12: volume down and up.\nSongs play through Suno's own player, hidden inside the app."),
            T("Audio output") + "\n" + T("Playback menu, Audio output: choose the output songs play on (headphones, speakers, a USB box), or the Windows default. Second audio output: one more, say external speakers to show someone a song; Ctrl+Shift+F12 switches to it and back, even mid-song. Both are also in Settings. Tin Pan always starts on the main output, and if an output is unplugged it says so and plays on the Windows default."),
            T("Library list") + "\n" + T("Enter: play.\nSpace: pause or resume.\nLeft and Right arrows: back and forward 5 seconds.\nCtrl+I: details (style, model, plays, link and lyrics) as one text.\nAlt+Enter: song information, one fact per line.\nCtrl+L: lyrics.\nCtrl+C: copy the song's link.\nCtrl+D: download in the format chosen in Settings. It uses the song's free unencrypted file when Suno has one; if the direct download fails, the app offers Suno's own download instead.\nCtrl+E: extend.\nDelete: move to Suno trash (asks first).\nApplications key or Shift+F10 for everything: Download WAV, Download video, Extend, Cover, Remaster, Get whole song, Stems, Edit title and lyrics, Make public or private, Add to playlist, Copy Suno share link, Allow or stop remixes, Similar songs, Show comments, Write a comment.\nWAV needs a Pro or Premier plan. Free plans get a few covers and remasters; the Song menu says how many are left, and Shift+F2 reads them out.\nReaching the end of the list loads more songs.\nAlt+F, Filters: workspace, disliked songs, trash, stems, Suno Studio songs, liked, public or private, uploaded, covers, extended, remasters, whole songs, personas, songs in a playlist and songs downloaded before. Each can show those songs, show only them, or hide them. Sort newest, oldest, most liked or least liked first. Kept between runs.\nAlt+L, Download all: every finished song in the list, using the free direct download only; songs already in the folder are skipped.\nSongs you liked say \"liked\".") + "\n" + T("In every song list (the Library, a playlist's songs, Trending and song windows): Ctrl+Shift+U like, Ctrl+Shift+N dislike, Ctrl+P add to a playlist, Ctrl+T edit the title and lyrics, Ctrl+Shift+C cover, Ctrl+Shift+M remaster, Ctrl+J get the whole song, Ctrl+Shift+S stems, Ctrl+Shift+D download MP3, Ctrl+Shift+W download WAV, Ctrl+Shift+V download the video, Ctrl+Shift+H clean up the download, Ctrl+M similar songs, Ctrl+U the creator's songs, Ctrl+O the original song, Ctrl+Shift+O covers and remixes of it, Ctrl+K comments, Ctrl+Shift+K write a comment, Ctrl+Shift+L copy the Suno share link, Ctrl+Shift+P public or private, Ctrl+Shift+X allow or stop remixes. The Song menu shows each key."),
            T("Search box") + "\n" + T("Enter searches, Escape clears the search."),
            T("Create window") + "\n" + T("Ctrl+N or New song on the Library page opens this window, which stays open beside the Library until you close it (Escape or Close). F6 goes to the main window and back, and the playback keys work here, so you can listen to what you made and make another.\nModel, style, styles to exclude, voice, instrumental, max mode, weirdness, style influence and persona (pick one of yours, or type an ID) apply to both ways of making a song.\nDescribe a song lets Suno write the words. Your own lyrics uses your title and lyrics. Write lyrics makes lyrics from a topic, and Use these lyrics copies them in.\nStyle boost rewrites the Style box into a fuller description.\nChange my lyrics: say what to change, then Rewrite my lyrics now. The result goes into Generated lyrics; Use these lyrics copies it in.\nNew songs appear at the top of your library. You'll hear when they're ready.\nIf Suno asks for a captcha, the app passes it itself. If Suno wants a click, a Suno check window comes forward with the check box.") + "\n" + T("Style ideas lists styles Suno suggests; Enter puts one in the Style box. Lyrics drafts lists your drafts from Suno's lyrics editor; Enter puts one in the Lyrics box, asking first if it has words in it."),
            T("Trending tab") + "\n" + T("Loads when you first open it. Enter plays a song and Space pauses or resumes; F9 and the end of a song carry on down the list. Each song says who made it. The Song menu's keys work here too, and the Applications key has every Song command."),
            T("Discover") + "\n" + T("Discover menu: Explore, Suno's shelves of songs (Enter opens one); From people I follow; Find a creator, by handle or link; and Contests (Enter plays a contest's song). Songs open in their own list, where Enter plays one and Escape closes it; each says who made it.\nSong menu, Related songs (also in the Applications key menu): Similar songs, Creator's songs, Covers and remixes of it, and Original song (what a cover, extension or whole song was made from)."),
            T("Account tab") + "\n" + T("Your plan, credits and what the plan includes, then Suno's notifications.") + "\n" + T("Notifications you haven't seen say New. Mark all as read (also in the Account menu) marks them read on Suno too."),
            T("Playlists tab") + "\n" + T("Left list: your playlists. Enter opens one, Delete moves it to the trash (asks first). New, Rename and Delete buttons.\nRight list: its songs. Enter plays and carries on through the playlist, Space pauses, Delete removes the song from the playlist, Ctrl+Up and Ctrl+Down move it."),
            T("Extend, Cover and Remaster") + "\n" + T("Each opens a form that stays open until you close it (Escape or Close). Tab moves between fields; the button at the bottom starts it, and you can change something and start another. F6 goes to the main window and back, and the playback keys work in the form, so you can listen while you fine-tune.\nExtend continues a song from a time you choose; then use Get whole song to join the parts.\nCover keeps the melody in a new style; you can change the title and lyrics, which start as the original words, and set audio influence, weirdness, style influence and persona. Remaster makes a cleaner version with a newer model: pick strength (Subtle, Normal, High), kind (Natural, Boost, Clarity) and, if you like, the fine controls.") + "\n" + T("In Cover, Rewrite the lyrics now changes the Lyrics box the way the How to change box says, and Back to the original words undoes it. Cover and Extend have Style boost and Style ideas for the Style box. You can start up to five at once, as Suno allows; the button waits only while five are still being started."),
            T("More you can do") + "\n" + T("Song menu: Not interested asks Suno to suggest fewer songs like it. Cover picture uses a picture from your computer, one Suno draws from a description, or Suno's own again. Delete forever (Shift+Delete) removes a song in the trash for good; Delete on a song in the trash restores it. Make from it has Make a video and Make a persona. Related songs has Its stems, Credits and remix count, and the creator's playlists, which you can like or save. Sharing can show or hide the list of remixes on the song's page.\nLibrary menu: Personas (yours, loved or followed: their songs, source song, rename, public or private, love, trash), Custom models (train one from a playlist of 6 to 100 of your songs, rename, archive) and Lyrics mashup. On the Playlists tab the Applications key adds Cover picture and Make an album from it.\nSongs play in Tin Pan itself, which starts them much sooner, and the next song in the list is fetched ahead; Suno's own player takes over when that fails. Settings can turn that off.") + "\n" +
            T("Changing a song") + "\n" + T("Song menu, Make from it: Change speed (keeping the pitch or not, like a tape), Reverse, Crop (keep only a part, or take a part out) and Fade in or out. Each opens a small form like Remaster and makes a new song; the original stays as it is. You hear when the new one is ready.") + "\n" +
            T("Speech") + "\n" + T("Help menu or Settings, Tin Pan speaks: everything; what you ask for and errors (no background news); or only errors and what you ask to hear. F1, F2, F3 and Ctrl+R always speak, and every message is kept in the history.\nSettings, When a list reaches the playing song: a short click (the default), say playing (also in braille), both, or nothing.") + "\n" + T("Shift+F3, or Settings, Live lyrics: when a song has timed lyrics, Tin Pan says each line as it starts, also in braille. Off to start with. Section tags such as [Chorus] aren't read."),
            T("Settings") + "\n" + T("Sign in opens Suno's own sign-in page; it closes by itself once you're in. It remembers your Google account and can save your password. Sign out only signs out of Suno. The first time, or when Suno ends your sign-in, Tin Pan asks you to sign in.\nLanguage: English, Romanian, Ukrainian or Spanish, or the same as Windows. It changes the next time Tin Pan starts.\nDownload folder, download format, and extra files saved next to each download: lyrics, timed lyrics (LRC), song details and cover art.\nCheck for new versions when Tin Pan starts: on by default, and quiet unless there is one."),
            T("Uploading") + "\n" + T("Library menu, Upload a song (Alt+U on the Library page), sends an audio file from this computer to your Suno account, where it becomes a song you can play, extend, cover and remaster. MP3, M4A, WAV, FLAC, OGG and AAC go as they are; WMA and other files Windows can play are converted to M4A first. You can add its lyrics. You confirm you have the rights to it and accept Suno's upload terms. Suno checks each upload, which can take a minute or two, and may refuse copyrighted music. The length limits are your plan's."),
            T("Clean-up") + "\n" + T("Download (Ctrl+D) asks every time whether to clean the song up with sunscreen, which removes the haze and buzz in Suno songs. Download MP3, Download WAV and Download all don't ask; they clean up when Settings says to. Clean up download, in the Song menu, cleans up a song you already have.\nThe result is a 24-bit WAV next to the download, with (clean) added to its name, often 10 to 20 times bigger. sunscreen reads MP3 and WAV, so Suno's M4A files are converted first. It runs on this computer and takes about 10 seconds for a 5-minute song.\nSettings has each step: decoder buzz, hearing model, flutter, widening, top octave, tone matching and loudness, with their values, and whether to keep the original download."),
            T("Problems and ideas") + "\n" + T("Help menu, Report a problem (Ctrl+Shift+B) and Suggest a feature (Ctrl+Shift+F) send a message privately to Tin Pan's author; no account is needed. A problem report can include Tin Pan's log, which has no passwords; your Windows user name is taken out first."),
            T("Updates") + "\n" + T("Help, Check for updates looks for a new version now. When one is out, Tin Pan says what's new and asks; Yes downloads it, checks its signature, closes Tin Pan, swaps in the new TinPan.exe and opens it again. Saying No at startup means that version isn't offered again by itself.")
        });
    }
}
